<?php require dirname(__DIR__).'/includes/functions.php'; require_admin(); $title='Messages'; require __DIR__.'/_header.php'; $messages=all('SELECT * FROM contact_messages ORDER BY id DESC'); if(!$messages): ?><div class="glass empty-state"><h2>Your inbox is clear.</h2></div><?php endif; foreach($messages as $m): ?><article class="glass p-4 mb-3"><div class="section-heading"><h2><?= e($m['subject']) ?></h2><small><?= e($m['created_at']) ?></small></div><p><?= e($m['name']) ?> · <?= e($m['email']) ?></p><p><?= nl2br(e($m['message'])) ?></p></article><?php endforeach; require __DIR__.'/_footer.php'; ?>
